namespace ZARI.Domain.Entities;

using ZARI.Domain.Common;

/// <summary>
/// The payslip itself — one row per employee per run, entirely regenerated by
/// ComputePayrollRunCommand while the run is DRAFT (see PayrollComputationService). Never silently
/// recalculated once the run is POSTED — same "the table IS the report" idiom as
/// LoanAmortizationScheduleLine, and this codebase's absolute rule against editing posted document
/// history. See HrModuleContext.md §3.14.
/// </summary>
public sealed class PayrollLine : AuditableEntity
{
    public Guid PayrollRunId { get; set; }
    public PayrollRun PayrollRun { get; set; } = default!;
    public Guid EmployeeId { get; set; }
    public Employee Employee { get; set; } = default!;

    public decimal BasicPay { get; set; }
    public decimal OvertimePay { get; set; }
    public decimal AllowanceTotal { get; set; }
    public decimal GrossPay { get; set; }

    public decimal SssEmployeeShare { get; set; }
    public decimal SssEmployerShare { get; set; }
    public decimal PhilHealthEmployeeShare { get; set; }
    public decimal PhilHealthEmployerShare { get; set; }
    public decimal PagIbigEmployeeShare { get; set; }
    public decimal PagIbigEmployerShare { get; set; }

    public decimal WithholdingTax { get; set; }
    public decimal DeductionTotal { get; set; }
    public decimal NetPay { get; set; }
}
